nextflow_process {

    name "Test Process QUARTONOTEBOOK"
    script "../main.nf"
    process "QUARTONOTEBOOK"

    tag "modules"
    tag "modules_nfcore"
    tag "quartonotebook"

    test("deprecated") {

        when {
            process {
                """
                input[0] = [ [ id:'test' ], file('notebook') ]
                input[1] = []
                input[2] = file('input_files')
                input[3] = file('extensions')
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains("WARNING: This module has been deprecated. Please use nf-core/modules/quarto/notebook instead.") }
            )
        }
    }
}
